problems.solutionCode:
type QueueNode<T> = { value: T; next: QueueNode<T> | null };
export class SinglyLinkedList<T> {
  private head: QueueNode<T> | null = null;
  private tail: QueueNode<T> | null = null;
  private count = 0;
  get length(): number { return this.count; }
  append(value: T): void {
    const node: QueueNode<T> = { value, next: null };
    if (this.tail === null) { this.head = node; this.tail = node; }
    else { this.tail.next = node; this.tail = node; }
    this.count += 1;
  }
  removeFirst(): T | undefined {
    if (this.head === null) return undefined;
    const removed = this.head;
    this.head = removed.next;
    if (this.head === null) this.tail = null;
    this.count -= 1;
    return removed.value;
  }
  toArray(): T[] {
    const values: T[] = [];
    let cursor = this.head;
    while (cursor !== null) { values.push(cursor.value); cursor = cursor.next; }
    return values;
  }
}

