type PlaylistNode<T> = { value: T; next: PlaylistNode<T> | null; previous: PlaylistNode<T> | null };
export class DoublyList<T> {
  private head: PlaylistNode<T> | null = null;
  private tail: PlaylistNode<T> | null = null;
  private count = 0;
  get length(): number { return this.count; }
  private nodeAt(index: number): PlaylistNode<T> | null {
    let cursor = this.head;
    for (let step = 0; step < index && cursor !== null; step += 1) cursor = cursor.next;
    return cursor;
  }
  private linkBefore(node: PlaylistNode<T>, target: PlaylistNode<T>): void {
    const added = node; const anchor = target; const previous = anchor.previous;
    added.previous = previous; added.next = anchor; anchor.previous = added;
    if (previous === null) this.head = added; else previous.next = added;
  }
  private linkAfterTail(node: PlaylistNode<T>): void {
    const added = node;
    if (this.tail === null) { this.head = added; this.tail = added; return; }
    added.previous = this.tail; this.tail.next = added; this.tail = added;
  }
  insertAt(index: number, value: T): boolean {
    if (!Number.isInteger(index) || index < 0 || index > this.count) return false;
    const node: PlaylistNode<T> = { value, next: null, previous: null };
    const target = this.nodeAt(index);
    if (index === 0 && target !== null) this.linkBefore(node, target);
    else if (target === null) this.linkAfterTail(node);
    else this.linkBefore(node, target);
    this.count += 1; return true;
  }
  private detach(node: PlaylistNode<T>): void {
    const detached = node;
    if (detached.previous === null) this.head = detached.next; else detached.previous.next = detached.next;
    if (detached.next === null) this.tail = detached.previous; else detached.next.previous = detached.previous;
    detached.next = null; detached.previous = null;
  }
  removeAt(index: number): T | undefined {
    if (!Number.isInteger(index) || index < 0 || index >= this.count) return undefined;
    const node = this.nodeAt(index); if (node === null) return undefined;
    this.detach(node); this.count -= 1; return node.value;
  }
  toArray(): T[] { const out: T[] = []; let cursor = this.head; while (cursor !== null) { out.push(cursor.value); cursor = cursor.next; } return out; }
  toReverseArray(): T[] { const out: T[] = []; let cursor = this.tail; while (cursor !== null) { out.push(cursor.value); cursor = cursor.previous; } return out; }
}

